<template><section class="diary-attachments"><header><strong>Imágenes y evidencias</strong><span>{{items.length}} / 20</span></header><p class="diary-hint">JPG, PNG, WebP, GIF, AVIF, BMP, TIFF, HEIC, SVG, PSD y otros formatos de imagen reconocidos. Hasta 20 MB por imagen. Los formatos sin vista previa se descargan.</p><label v-if="!readonly && !locked" class="diary-upload-zone">＋ {{uploading?'Subiendo imágenes…':'Seleccionar imágenes'}}<input type="file" multiple accept="image/*,.heic,.heif,.psd,.raw,.cr2,.cr3,.nef,.arw,.dng,.orf,.rw2,.raf,.ai,.eps" :disabled="uploading" @change="upload"></label><p v-if="locked" class="diary-hint">Evidencias protegidas: esta actividad ya fue evaluada o cancelada.</p><p v-if="status" class="diary-hint" role="status">{{status}}</p><p v-if="error" class="diary-error" role="alert">{{error}}</p><div class="diary-attachment-grid"><article v-for="a in items" :key="a.Id"><a :href="fileUrl(a)+(a.VistaPrevia?'?vista=1':'')" target="_blank" rel="noopener"><img v-if="a.VistaPrevia" :src="fileUrl(a)+'?vista=1'" :alt="a.Nombre" loading="lazy"><span v-else class="diary-file-icon">▧<small>{{extension(a.Nombre)}}</small></span></a><strong :title="a.Nombre">{{a.Nombre}}</strong><small>{{size(a.Tamano)}} · {{a.Usuario}}</small><div><a :href="fileUrl(a)" target="_blank" rel="noopener">Descargar</a><button v-if="a.PuedeEliminar && !readonly" type="button" :disabled="uploading" @click="remove(a)">Eliminar</button></div></article></div><p v-if="!items.length && !loading" class="diary-hint">Aún no hay imágenes adjuntas.</p></section></template>
<script>
import config from '@/store/config';
export default {props:{taskId:{required:true},context:{type:Object,required:true},readonly:Boolean},data(){return {items:[],locked:false,loading:false,uploading:false,error:'',status:''}},mounted(){this.load()},methods:{
 fileUrl(a){return config.API+'diario/adjuntos/'+a.Id},extension(n){return n.split('.').pop().toUpperCase().slice(0,8)},size(n){return n>1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB'},message(e){return e.response&&e.response.data.error||'No se pudo completar la carga. Actualiza la lista para comprobar los archivos recibidos.'},
 async load(){this.loading=true;try{const r=await this.axios.get(config.API+'diario/tareas/'+this.taskId+'/adjuntos',{timeout:15000});this.items=r.data.adjuntos;this.$emit('count',this.items.length);this.locked=r.data.bloqueado}catch(e){this.error=this.message(e)}finally{this.loading=false}},
 async upload(e){if(this.uploading)return;const files=Array.from(e.target.files||[]);if(!files.length)return;this.uploading=true;this.$emit('busy',true);this.error='';let count=0;try{for(const file of files){if(this.items.length+count>=20)throw Error('Máximo 20 imágenes por actividad.');if(file.size>20*1024*1024)throw Error(file.name+': supera los 20 MB.');this.status='Subiendo '+(count+1)+' de '+files.length+'…';const body=new FormData();body.append('imagen',file);await this.axios.post(config.API+'diario/tareas/'+this.taskId+'/adjuntos',body,{headers:{'X-Diario-CSRF':this.context.csrf},timeout:120000});count++;}this.status=count+' imágenes guardadas.'}catch(error){this.error=error.response?this.message(error):error.message;this.status=count+' imágenes guardadas antes de detener la carga.'}finally{e.target.value='';await this.load();this.uploading=false;this.$emit('busy',false)}},
 async remove(a){if(!window.confirm('¿Eliminar la imagen «'+a.Nombre+'»?'))return;this.uploading=true;this.$emit('busy',true);this.error='';try{await this.axios.post(config.API+'diario/adjuntos/'+a.Id+'/eliminar',{}, {headers:{'X-Diario-CSRF':this.context.csrf},timeout:15000});await this.load()}catch(e){this.error=this.message(e)}finally{this.uploading=false;this.$emit('busy',false)}}
}};
</script>
<style>.diary-attachments{margin:18px 0;padding:16px;background:#f7fafc;border:1px solid #e0e9f0;border-radius:13px}.diary-attachments>header{display:flex;justify-content:space-between;align-items:center;color:#2c4d64;font-size:13px}.diary-attachments>header>span{font-size:10px;color:#7c94a4}.diary-upload-zone{display:flex!important;align-items:center;padding:17px;border:1px dashed #a8c9d8;border-radius:9px;background:#edf6f8;color:#337385!important;cursor:pointer;font-size:12px!important;text-align:center;margin:12px 0!important}.diary-upload-zone input{width:100%;font-size:11px!important;padding:6px!important;background:transparent!important;border:0!important}.diary-attachment-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px;margin-top:14px}.diary-attachment-grid article{background:white;border:1px solid #e0e9f0;padding:8px;border-radius:10px;min-width:0}.diary-attachment-grid img{width:100%;height:115px;object-fit:contain;background:#eef3f6;border-radius:6px}.diary-attachment-grid strong{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;margin:7px 0 4px}.diary-attachment-grid article>small{display:block;font-size:9px;color:#7d94a4}.diary-attachment-grid article>div{display:flex;justify-content:space-between;align-items:center;margin-top:8px;gap:6px;font-size:10px}.diary-attachment-grid article>div>button{padding:3px 6px!important;background:#fff2ef!important;color:#af6b54!important;font-size:9px!important;border:0!important}.diary-file-icon{height:115px;display:flex;flex-direction:column;align-items:center;justify-content:center;background:#edf3f6;color:#668ca1;font-size:34px;border-radius:6px}.diary-file-icon small{font-size:10px}.diary-attachments .diary-hint{font-size:10px;line-height:1.7}</style>
